 @Test void plaintextDefaultsNullableMaximumAndAllCopiesAreIndependent()throws Exception{
  var f=ready();var before=templates.detail(admin.principal(),f.template());templates.updateStage(admin.principal(),f.template(),f.stage(),before.version(),"Station",60000L,null);
  assertTrue(templates.readiness(admin.principal(),f.template()).ready());assertEquals(0,templates.stageDetail(admin.principal(),f.template(),f.stage()).maxPenaltyPoints());
  templates.update(admin.principal(),f.template(),version(f.template()),"Source",null,-3,17L);override(f,null,null);
  var inherited=templates.stageDetail(admin.principal(),f.template(),f.stage()).code();assertNull(inherited.wrongAttemptPenaltyPoints());assertEquals(17,inherited.effectiveWrongAttemptPenaltyPoints());assertEquals("SYNTHETIC-CODE",inherited.value());
  templates.state(admin.principal(),f.template(),version(f.template()),"READY");var event=create(f);var frozen=events.stages(admin.principal(),event.id()).getFirst();assertEquals(0,frozen.maxPenaltyPoints());assertEquals(17,frozen.code().effectiveWrongAttemptPenaltyPoints());assertNull(frozen.code().wrongAttemptPenaltyPoints());assertEquals("SYNTHETIC-CODE",frozen.code().value());assertEquals("Source",events.detail(admin.principal(),event.id()).sourceTemplateName());assertTrue(events.detail(admin.principal(),event.id()).sourceTemplateNameIsSnapshot());
  templates.update(admin.principal(),f.template(),version(f.template()),"Renamed",null,-3,29L);override(f,0L," new-code ");
  var explicit=templates.stageDetail(admin.principal(),f.template(),f.stage()).code();assertEquals(0,explicit.wrongAttemptPenaltyPoints());assertEquals(0,explicit.effectiveWrongAttemptPenaltyPoints());assertEquals("NEW-CODE",explicit.value());
  assertEquals(frozen,events.stages(admin.principal(),event.id()).getFirst());assertEquals(17,events.detail(admin.principal(),event.id()).defaultWrongCodePenaltyPoints());assertEquals("Source",events.list(admin.principal(),null,0,100).items().stream().filter(e->e.id().equals(event.id())).findFirst().orElseThrow().sourceTemplateName());
  var stageCopy=copies.duplicateStage(admin.principal(),f.template(),f.stage(),version(f.template()),UUID.randomUUID());assertEquals("NEW-CODE",templates.stageDetail(admin.principal(),f.template(),stageCopy.id()).code().value());
  var copy=copies.duplicate(admin.principal(),f.template(),UUID.randomUUID());assertEquals(29,templates.detail(admin.principal(),copy.id()).defaultWrongCodePenaltyPoints());assertTrue(templates.detail(admin.principal(),copy.id()).stages().stream().allMatch(stage->"NEW-CODE".equals(stage.code().value())&&stage.code().effectiveWrongAttemptPenaltyPoints()==0));
  String metadata=String.join("",jdbc.queryForList("SELECT coalesce(metadata::text,'') FROM audit_event",String.class));String ledger=String.join("",jdbc.queryForList("SELECT coalesce(request_data::text,'')||coalesce(result_data::text,'') FROM admin_role_command",String.class));assertFalse(metadata.contains("NEW-CODE"));assertFalse(ledger.contains("NEW-CODE"));
 }
 @Test void nonAdministratorCannotReadPlaintextCodeFromTemplateOrAction()throws Exception{var f=ready();var event=create(f);var ordinary=actor();for(String url:List.of("/api/v1/race-templates/"+f.template(),"/api/v1/race-templates/"+f.template()+"/stages/"+f.stage(),"/api/v1/race-events/"+event.id()+"/stages")){String response=mvc.perform(get(url).header("Authorization","Bearer "+ordinary.token())).andExpect(status().isForbidden()).andReturn().getResponse().getContentAsString();assertFalse(response.contains("SYNTHETIC-CODE"));}}
 @Test void deleteActionRemovesSnapshotFilesAndAuditsExactlyOnce()throws Exception{var f=ready();var event=create(f);mvc.perform(delete("/api/v1/race-events/"+event.id()).param("version","0").header("Authorization","Bearer "+admin.token())).andExpect(status().isNoContent()).andExpect(content().string(""));assertEquals(0,count("SELECT count(*) FROM race_event WHERE id=?",event.id()));assertEquals(0,count("SELECT count(*) FROM event_stage WHERE race_event_id=?",event.id()));assertEquals(0,count("SELECT count(*) FROM event_file WHERE race_event_id=?",event.id()));assertFalse(Files.exists(DIR.resolve("events/race-events/"+event.id()+"/images/map.png")));assertTrue(Files.exists(DIR.resolve("templates/race-templates/"+f.template()+"/images/map.png")));assertEquals(1,count("SELECT count(*) FROM audit_event WHERE target_id=? AND event_type='RACE_EVENT_DELETED'",event.id()));assertEquals(404,assertThrows(AuthFailure.class,()->events.delete(admin.principal(),event.id(),0)).status());templates.delete(admin.principal(),f.template(),version(f.template()));}
 @Test void failedDeleteAuditPreservesWholeSnapshotAndFiles()throws Exception{var f=ready();var event=create(f);var detail=events.detail(admin.principal(),event.id());byte[] png=events.file(admin.principal(),event.id(),"map.png").bytes();var fail=new AtomicBoolean(true);doAnswer(i->{Object result=i.callRealMethod();if(fail.get())throw new IllegalStateException("Injected delete audit failure");return result;}).when(audit).appendRace(any(),any(),any(),eq(Event.RACE_EVENT_DELETED),eq(event.id()),any(),anyLong());assertThrows(RuntimeException.class,()->events.delete(admin.principal(),event.id(),0));assertEquals(detail,events.detail(admin.principal(),event.id()));assertEquals(3,events.files(admin.principal(),event.id()).size());assertArrayEquals(png,events.file(admin.principal(),event.id(),"map.png").bytes());assertEquals(0,count("SELECT count(*) FROM audit_event WHERE target_id=? AND event_type='RACE_EVENT_DELETED'",event.id()));fail.set(false);events.delete(admin.principal(),event.id(),0);assertEquals(0,count("SELECT count(*) FROM race_event WHERE id=?",event.id()));}
 @Test void concurrentDeletesHaveOneWinnerAndFutureSchemaPreventsDeletion()throws Exception{var f=ready();var event=create(f);Callable<String> deletion=()->{try{events.delete(admin.principal(),event.id(),0);return "DELETED";}catch(AuthFailure failure){return failure.code();}};var results=race(deletion,deletion);assertEquals(1,results.stream().filter("DELETED"::equals).count());assertEquals(1,results.stream().filter("RACE_EVENT_NOT_FOUND"::equals).count());assertEquals(1,count("SELECT count(*) FROM audit_event WHERE target_id=? AND event_type='RACE_EVENT_DELETED'",event.id()));var kept=create(f);int rank=jdbc.queryForObject("SELECT max(installed_rank)+1 FROM flyway_schema_history",Integer.class);jdbc.update("INSERT INTO flyway_schema_history(installed_rank,version,description,type,script,installed_by,execution_time,success) VALUES (?,'28','Unknown participation migration','SQL','V28__unknown.sql',current_user,0,true)",rank);try{assertEquals("RACE_EVENT_USAGE_CHECK_UNAVAILABLE",assertThrows(AuthFailure.class,()->events.delete(admin.principal(),kept.id(),0)).code());assertNotNull(events.detail(admin.principal(),kept.id()));assertEquals(3,events.files(admin.principal(),kept.id()).size());}finally{jdbc.update("DELETE FROM flyway_schema_history WHERE installed_rank=?",rank);}}
 @Test void minuteTimesRoundTripThroughPostgresAndJson()throws Exception{var f=ready();Instant start=OffsetDateTime.parse("2026-11-01T11:20:00+01:00").toInstant(),end=OffsetDateTime.parse("2026-11-01T17:45:00+01:00").toInstant();var input=new EventService.Input("Minutes",null,start,end);var event=events.create(admin.principal(),f.template(),version(f.template()),UUID.randomUUID(),input);var detail=events.detail(admin.principal(),event.id());assertEquals(start,detail.scheduledStartAt());assertEquals(end,detail.endAt());assertEquals(0,detail.scheduledStartAt().getNano());assertEquals(detail,events.update(admin.principal(),event.id(),0,input));mvc.perform(get("/api/v1/race-events/"+event.id()).header("Authorization","Bearer "+admin.token())).andExpect(status().isOk()).andExpect(jsonPath("$.scheduledStartAt").value("2026-11-01T10:20:00Z")).andExpect(jsonPath("$.endAt").value("2026-11-01T16:45:00Z")).andExpect(jsonPath("$.sourceTemplateName").value("Source"));}
 @Test void upgradeV21ToV22PreservesLegacyHashesAndFlagsUnrecoverableCodes(){String schema=SCHEMA+"_v22";assertTrue(schema.matches("it_events_[0-9a-f]{32}_v22"));var source=jdbc.getDataSource();UUID template=UUID.randomUUID(),stage=UUID.randomUUID(),event=UUID.randomUUID(),eventStage=UUID.randomUUID();try{org.flywaydb.core.Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("21").load().migrate();jdbc.update("INSERT INTO "+schema+".race_template(id,name,skip_penalty_points,status,version,created_at,updated_at) VALUES (?,'Legacy name',-3,'READY',7,now(),now())",template);jdbc.update("INSERT INTO "+schema+".template_stage(id,race_template_id,sequence_no,name,instructions_markdown,code_enabled,code_hash,wrong_code_penalty_points,max_penalty_points) VALUES (?,?,1,'Legacy','Original',true,'old-hash-only',-7,NULL)",stage,template);jdbc.update("INSERT INTO "+schema+".race_event(id,source_template_id,source_template_version,name,skip_penalty_points,created_at,updated_at) VALUES (?,?,7,'Legacy action',-3,now(),now())",event,template);jdbc.update("INSERT INTO "+schema+".event_stage(id,race_event_id,source_template_stage_id,sequence_no,name,instructions_markdown,code_enabled,code_hash,wrong_code_penalty_points) VALUES (?,?,?,1,'Snapshot','Snapshot',true,'old-hash-only',-7)",eventStage,event,stage);org.flywaydb.core.Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("22").load().migrate();assertEquals("DRAFT",jdbc.queryForObject("SELECT status FROM "+schema+".race_template WHERE id=?",String.class,template));assertEquals(8,count("SELECT version FROM "+schema+".race_template WHERE id=?",template));assertEquals("PLANNED",jdbc.queryForObject("SELECT status FROM "+schema+".race_event WHERE id=?",String.class,event));assertEquals(0,count("SELECT version FROM "+schema+".race_event WHERE id=?",event));for(String table:List.of("template_stage","event_stage")){assertEquals("old-hash-only",jdbc.queryForObject("SELECT code_hash FROM "+schema+"."+table,String.class));assertNull(jdbc.queryForObject("SELECT code_value FROM "+schema+"."+table,String.class));assertEquals(-7,count("SELECT wrong_code_penalty_points FROM "+schema+"."+table));}assertEquals("Legacy name",jdbc.queryForObject("SELECT source_template_name FROM "+schema+".race_event",String.class));assertFalse(jdbc.queryForObject("SELECT source_template_name_is_snapshot FROM "+schema+".race_event",Boolean.class));assertEquals(0,count("SELECT default_wrong_code_penalty_points FROM "+schema+".race_event"));assertEquals("Snapshot",jdbc.queryForObject("SELECT instructions_markdown FROM "+schema+".event_stage",String.class));assertEquals(1,count("SELECT count(*) FROM "+schema+".audit_event WHERE metadata->>'reason'='CODE_VALUE_REQUIRED'"));}finally{jdbc.execute("DROP SCHEMA "+schema+" CASCADE");}}


 @Test void editInstructionsOnlyChangesOwnSnapshotAndReturnsRenderedLinks()throws Exception{var f=ready();var first=create(f);var other=create(f);var before=events.stages(admin.principal(),first.id()).getFirst();var originalTemplate=templates.detail(admin.principal(),f.template());var originalOther=events.stages(admin.principal(),other.id());String text="# New\n\n![Map](map.png) [Guide](/api/v1/race-events/"+first.id()+"/files/guide.md#part) [Missing](later.pdf) <script>alert(1)</script>";var result=events.updateInstructions(admin.principal(),first.id(),before.id(),0,text);assertEquals(1,result.version());assertEquals(text,result.instructionsMarkdown());assertEquals(1,result.missingReferences().size());assertTrue(result.instructionsRenderedHtml().contains("/race-events/"+first.id()+"/files/map.png"));assertFalse(result.instructionsRenderedHtml().contains("<script>"));assertEquals(originalTemplate,templates.detail(admin.principal(),f.template()));assertEquals(originalOther,events.stages(admin.principal(),other.id()));var after=events.stages(admin.principal(),first.id()).getFirst();assertEquals(before.code(),after.code());assertEquals(before.gps(),after.gps());assertEquals(before.timePenalty(),after.timePenalty());assertEquals(before.delayed(),after.delayed());assertEquals(before.name(),after.name());assertEquals(before.sequenceNo(),after.sequenceNo());assertEquals(before.maxPenaltyPoints(),after.maxPenaltyPoints());assertEquals(before.expectedDurationMs(),after.expectedDurationMs());assertEquals(3,events.files(admin.principal(),first.id()).size());assertEquals(result,events.updateInstructions(admin.principal(),first.id(),before.id(),1,text));assertEquals(1,count("SELECT count(*) FROM audit_event WHERE target_id=? AND event_type='RACE_EVENT_STAGE_INSTRUCTIONS_UPDATED'",first.id()));String metadata=jdbc.queryForObject("SELECT metadata::text FROM audit_event WHERE target_id=? AND event_type='RACE_EVENT_STAGE_INSTRUCTIONS_UPDATED'",String.class,first.id());assertTrue(metadata.contains(before.id().toString()));assertFalse(metadata.contains("New"));assertEquals("RACE_EVENT_VERSION_CONFLICT",assertThrows(AuthFailure.class,()->events.updateInstructions(admin.principal(),first.id(),before.id(),0,text)).code());assertNull(events.updateInstructions(admin.principal(),first.id(),before.id(),1,null).instructionsRenderedHtml());assertEquals(2,events.detail(admin.principal(),first.id()).version());}
 @Test void instructionsHttpAndForeignStageAreProtected()throws Exception{var f=ready();var a=create(f);var b=create(f);UUID stage=events.stages(admin.principal(),a.id()).getFirst().id(),foreign=events.stages(admin.principal(),b.id()).getFirst().id();String url="/api/v1/race-events/"+a.id()+"/stages/"+stage+"/instructions";var ordinary=actor();mvc.perform(put(url).header("Authorization","Bearer "+ordinary.token()).contentType("application/json").content("{\"version\":0,\"instructionsMarkdown\":\"Changed\"}")).andExpect(status().isForbidden());mvc.perform(put(url).header("Authorization","Bearer "+admin.token()).contentType("application/json").content("{\"version\":0,\"instructionsMarkdown\":\"Changed\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.version").value(1)).andExpect(jsonPath("$.instructionsMarkdown").value("Changed"));assertEquals("RACE_EVENT_STAGE_NOT_FOUND",assertThrows(AuthFailure.class,()->events.updateInstructions(admin.principal(),a.id(),foreign,1,"Other")).code());mvc.perform(get("/api/v1/race-events/"+a.id()+"/stages/"+stage).header("Authorization","Bearer "+admin.token())).andExpect(status().isOk()).andExpect(jsonPath("$.instructionsMarkdown").value("Changed"));}
 @Test void instructionsAuditFailureRollsBackTextVersionAndTimestamp()throws Exception{var f=ready();var a=create(f);var before=events.detail(admin.principal(),a.id());var stages=events.stages(admin.principal(),a.id());UUID stage=stages.getFirst().id();var fail=new AtomicBoolean(true);doAnswer(i->{Object result=i.callRealMethod();if(fail.get())throw new IllegalStateException("Injected instructions audit failure");return result;}).when(audit).appendRaceInstructions(any(),any(),any(),eq(a.id()),eq(stage));assertThrows(RuntimeException.class,()->events.updateInstructions(admin.principal(),a.id(),stage,0,"Rollback text"));assertEquals(before,events.detail(admin.principal(),a.id()));assertEquals(stages,events.stages(admin.principal(),a.id()));assertEquals(0,count("SELECT count(*) FROM audit_event WHERE target_id=? AND event_type='RACE_EVENT_STAGE_INSTRUCTIONS_UPDATED'",a.id()));fail.set(false);assertEquals(1,events.updateInstructions(admin.principal(),a.id(),stage,0,"Retry").version());}
